"""Check whether brackets in text are correctly balanced."""

_OPENING = '([{'
_CLOSING = ')]}'
_PAIRS = {')': '(', ']': '[', '}': '{'}


def balanced(s: str) -> bool:
    """Return whether brackets in *s* are balanced and correctly nested.

    Brackets inside double-quoted strings are ignored. Within a quoted string,
    a backslash escapes the following character, and an unterminated string is
    unbalanced.
    """
    stack: list[str] = []
    in_string = False
    escaped = False

    for char in s:
        if in_string:
            if escaped:
                escaped = False
            elif char == '\\':
                escaped = True
            elif char == '"':
                in_string = False
        elif char == '"':
            in_string = True
        elif char in _OPENING:
            stack.append(char)
        elif char in _CLOSING:
            if not stack or stack.pop() != _PAIRS[char]:
                return False

    return not in_string and not stack
